private int countWord(BTree tree, String word) {
    int result = 0;
    if (tree.isEmpty()) {
        return 0;
    } else if (tree.getInfo().equals(word)) {
        result = 1;
    }
    result = result + countWord(tree.getLeft(), word) + countWord(tree.getRight(), word);
    return result;
}

