explicame detalladamente este codigo public void insert(E info){
    Node newNode = new Node(info);
    Node current, previous;
    boolean found;
    boolean isEqual;
    if (first == null) {
        first = newNode;
    } else {
        current = first;
        previous = first;
        found = false;
        isEqual = false;
        while ( (current!=null) && (!found) && (!isEqual) ){
            isEqual = current.getInfo().compareTo(info) == 0;
            if (!isEqual){
                found = current.getInfo().compareTo(info)> 0;
                if (!found){
                    previous = current;
                    current = current.getNext();
                }
            }
        }
        if (!isEqual){
            if (previous == current){ // at the beginning
                newNode.setNext(first);
                first = newNode;
            }else{
                //this works at the end and at the middle
                previous.setNext(newNode);
                newNode.setNext(current);
            }
        }
    }
}

